import {RacingGarage,RaceSimulation,CARS,DIFFICULTIES,UPGRADE_COSTS,carById,raceTelemetry} from './racing-model.js';
import {drawRaceCar,drawRaceScene,drawFrontCar} from './racing-art.js';

import {RacingAudio} from './racing-audio.js';

export function mountRacing(root,api){
 root.innerHTML=`<header class="race-heading"><div class="race-brand"><button id="race-games" type="button" aria-label="다른 게임 선택">←</button><div><small>SPEED GARDEN</small><h1>스피드 정원</h1></div></div><div class="race-wallet"><span id="race-stage">STAGE 1</span><strong id="race-coins">🪙 500</strong><button id="race-records-open" type="button" aria-label="나의 레이싱 기록">🏆</button><button id="race-sound" type="button" aria-label="소리 켜기 또는 끄기">🔊</button></div></header>
 <div id="race-garage"><nav class="race-quick" aria-label="차량 메뉴"><button id="race-garage-open" type="button"><svg viewBox="0 0 24 24"><path d="M3 21V8l9-5 9 5v13M7 21V11h10v10M7 15h10M7 18h10"/></svg><span>차고</span></button><button id="race-shop-open" type="button"><svg viewBox="0 0 24 24"><path d="M3 9l2-6h14l2 6M4 9v12h16V9M2 9h20M9 21v-7h6v7"/></svg><span>상점</span></button><button id="race-upgrade-open" type="button"><svg viewBox="0 0 24 24"><path d="M14 4a6 6 0 0 0-7 7L2 17l5 5 6-6a6 6 0 0 0 7-7l-4 3-4-4 3-4"/></svg><span>업그레이드</span></button></nav>
 <section class="race-showroom"><div class="race-mode-tabs" id="race-drive-modes"><button data-drive-mode="drive" type="button">일반 도로주행<small>체력을 지키며 달려요</small></button><button data-drive-mode="race" type="button">레이싱<small>7대 경쟁 · 3위 안에 도전</small></button></div><div class="race-car-stage"><span class="race-car-stage-label">MY GARAGE / 01</span><canvas id="race-front-car" width="1000" height="560" aria-label="선택한 차량의 사선 모습"></canvas><div class="race-car-info"><small id="race-selected-tag"></small><h2 id="race-hero-name"></h2><span id="race-hero-spec"></span><div class="race-hero-bars" id="race-hero-bars"></div></div></div></section>
 <div class="race-lobby-bottom"><section class="race-difficulty-section"><h2 id="race-route-label">레이스 난이도</h2><div id="race-difficulties" class="race-difficulties"></div></section><div class="race-launch"><button id="race-fresh" type="button" class="race-secondary" hidden>새로 출발</button><button id="race-start" type="button" class="race-primary">🏁 레이스 출발</button></div><p class="race-save-note" id="race-save-note" role="status">차량 · 동전 · 주행 자동 저장</p></div></div>
 <section id="race-play" class="race-play" hidden aria-label="스피드 정원 주행"><canvas id="race-canvas" width="1200" height="1440" tabindex="0" aria-label="방향키 또는 WASD로 가속과 조향, 도로 곳곳의 부스트 발판을 밟아 가속하세요."></canvas><div class="race-hud"><div class="race-hud-top"><div><small id="race-hud-stage">STAGE 1</small><strong class="race-hud-name">주행 중</strong><span id="race-hud-diff"></span></div><div><strong id="race-collected">🪙 +0</strong><button type="button" id="race-pause" aria-label="주행 일시정지">Ⅱ</button><button type="button" id="race-home">차고로</button></div></div><div class="race-progress"><div><span id="race-progress-start">START</span><strong id="race-position">7위 / 7대</strong><span id="race-progress-end">FINISH 🏁</span></div><div class="race-progress-track" id="race-track"><i id="race-progress-fill"></i><b id="race-player-marker">🏎️</b></div></div><p id="race-pad-status" class="race-pad-status">도로 곳곳의 부스트 발판을 밟아보세요 ⚡</p><p id="race-event" class="race-event" hidden role="status"></p></div><div id="race-countdown" class="race-countdown" aria-live="polite"></div><div class="race-controls"><div class="race-pedals"><div><button type="button" data-drive="left" aria-label="왼쪽 조향">◀</button><button type="button" data-drive="right" aria-label="오른쪽 조향">▶</button></div><div class="race-dashboard" aria-label="속도와 엔진 회전수"><svg viewBox="0 0 220 130" aria-hidden="true"><path class="dial-base" d="M22 104a88 88 0 1 1 176 0"/><path class="dial-red" d="M176 46a88 88 0 0 1 22 58"/><g class="dial-ticks"><path d="M30 103h9M39 66l8 4M65 37l5 8M110 20v10M155 37l-5 8M181 66l-8 4M190 103h-9"/></g><g id="race-rpm-needle"><path d="M110 104L37 92"/><circle cx="110" cy="104" r="5"/></g><text x="22" y="122">0</text><text x="105" y="17">4</text><text x="192" y="122">8</text></svg><svg class="speed-dial" viewBox="0 0 220 130" aria-hidden="true"><path class="dial-base" d="M22 104a88 88 0 1 1 176 0"/><g class="dial-ticks"><path d="M30 103h9M39 66l8 4M65 37l5 8M110 20v10M155 37l-5 8M181 66l-8 4M190 103h-9"/></g><g id="race-speed-needle"><path d="M110 104L37 92"/><circle cx="110" cy="104" r="5"/></g><text x="22" y="122">0</text><text x="100" y="17">160</text><text x="183" y="122">320</text></svg><div class="dial-speed"><b id="race-speed">0</b><small>km/h</small></div><div class="dial-rpm"><span id="race-gear">D1</span><b id="race-rpm">850</b><small>RPM</small></div></div><div><button type="button" data-drive="accel" class="race-accel">↑<small>엑셀</small></button></div></div></div><div id="race-paused" class="race-paused" hidden><strong>잠깐, 피트 스톱</strong><p>준비되면 다시 출발해요.</p><button type="button" id="race-resume" class="race-primary">이어서 달리기 →</button></div><div id="race-result" class="race-result" hidden><div><div id="race-result-icon">🏆</div><h2 id="race-result-title"></h2><p id="race-result-stage"></p><dl id="race-result-details"></dl><p id="race-result-status" role="status"></p><div><button type="button" id="race-result-garage" class="race-secondary">차고 · 업그레이드</button><button type="button" id="race-result-next" class="race-primary">다음 스테이지 →</button></div></div></div></section>`;
 const makePanel=(id,title,content)=>{const d=document.createElement('dialog');d.id=id;d.className='race-panel';d.innerHTML=`<header><div><small>SPEED GARDEN</small><h2>${title}</h2></div><strong class="race-panel-coins"></strong><button class="dialog-close" type="button" aria-label="닫기">×</button></header>${content}`;d.querySelector('button').onclick=()=>d.close();document.body.append(d);return d;};
 const carPanel=makePanel('race-cars-dialog','내 차고','<p>보유한 차량을 선택하세요.</p><div id="race-owned-grid" class="race-car-grid"></div>');
 const shopPanel=makePanel('race-shop-dialog','차량 상점','<nav id="race-categories"><button data-category="all" type="button">전체 18</button><button data-category="luxury" type="button">프리미엄 11</button><button data-category="supercar" type="button">슈퍼카 7</button></nav><div id="race-car-grid" class="race-car-grid"></div>');
 const tuningPanel=makePanel('race-tuning-dialog','업그레이드','<div class="race-section-heading"><span id="race-selected"></span><strong id="race-spec"></strong></div><p>엔진 · 핸들링 · 니트로 / 최대 Lv.5</p><div id="race-upgrades" class="race-upgrades"></div>');
 const $=id=>document.getElementById(id),canvas=$('race-canvas'),ctx=canvas.getContext('2d');ctx.setTransform(2,0,0,2,0,0);
 const engine=new RacingAudio(),heldKeys=new Set(),touches=new Map();let garage=null,race=null,last=0,autosave=0,manualPause=false,settled=null,hasResult=false;
 // Refresh the selected photo and vehicle thumbnails once the sprite atlas decodes.
 globalThis.addEventListener?.('garden-racing-photos-ready',()=>{if(garage&&active()&&root.dataset.raceView!=='play')renderGarage();});
 const active=()=>api.current()==='racing',blocked=()=>!active()||document.hidden||!!document.querySelector('dialog[open]');
 const safe=fn=>{try{return fn();}catch(error){api.toast(error.message||'레이스를 준비하지 못했어요.');return null;}};
 const resetInputs=()=>{physicalKeys.clear();heldKeys.clear();touches.clear();for(const b of root.querySelectorAll('[data-drive]'))b.classList.remove('pressed');engine.mute();};
 const drive=()=>Object.fromEntries(['left','right','accel'].map(k=>[k,heldKeys.has(k)||[...touches.values()].includes(k)]));
 const money=n=>n.toLocaleString('ko-KR');
 function save(){if(!garage)return;try{if(race&&['countdown','racing'].includes(race.phase))garage.checkpoint(race);else garage.save();$('race-save-note').textContent='차량 · 동전 · 레이스 자동 저장';}catch(error){$('race-save-note').textContent='저장 공간을 확인해 주세요. 현재 화면에서 다시 시도할 수 있어요.';throw error;}}
 function updateWallet(){$('race-coins').textContent='🪙 '+money(garage.data.coins);$('race-stage').textContent='STAGE '+garage.data.stage;$('race-sound').textContent=api.settings?.().sound?'🔊':'🔇';}
 function renderGarage(){
  const p=garage.data,car=garage.car,u=p.upgrades[car.id];updateWallet();for(const d of [carPanel,shopPanel,tuningPanel])d.querySelector('.race-panel-coins').textContent='🪙 '+money(p.coins);$('race-hero-name').textContent=car.name;$('race-hero-spec').textContent=car.maxSpeed+' km/h · '+['엔진','핸들링','발판 부스트'].map((x,i)=>x+' '+u[['speed','handling','nitro'][i]]).join(' / ');$('race-selected-tag').textContent=car.tag;$('race-hero-bars').innerHTML=[['최고속력',Math.min(100,car.maxSpeed/4.22)],['가속력',Math.min(100,car.scrollSpeed/20*100)],['핸들링',Math.min(100,car.handling*650)],['부스트',Math.min(100,car.nitroPower*50)]].map(([name,n])=>`<span>${name}<i><b style="width:${n}%"></b></i></span>`).join('');const fc=$('race-front-car').getContext('2d');fc.clearRect(0,0,1000,560);drawFrontCar(fc,car);for(const b of $('race-drive-modes').children)b.setAttribute('aria-pressed',String(b.dataset.driveMode===p.selectedDriveMode));$('race-route-label').textContent=p.selectedDriveMode==='drive'?'주행할 도로':'레이스 난이도';$('race-selected').textContent=car.name;$('race-spec').textContent=`최고속도 ${car.maxSpeed} km/h`;$('race-upgrades').replaceChildren();
  for(const [key,label,icon]of [['speed','엔진','🚀'],['handling','서스펜션','🛞'],['nitro','발판 부스트','⚡']]){const card=document.createElement('div'),b=document.createElement('button');card.innerHTML=`<div><strong>${icon} ${label}</strong><span>Lv.${u[key]} / 5</span></div><progress max="5" value="${u[key]}" aria-label="${label} 레벨"></progress>`;b.type='button';b.dataset.upgrade=key;b.textContent=u[key]===5?'MAX':`🪙 ${money(UPGRADE_COSTS[u[key]])}`;b.disabled=u[key]===5||p.coins<UPGRADE_COSTS[u[key]];b.onclick=()=>safe(()=>{garage.upgrade(key);api.effect('special');renderGarage();});card.append(b);$('race-upgrades').append(card);}
  for(const b of $('race-categories').children)b.setAttribute('aria-pressed',String(b.dataset.category===p.selectedCategory));$('race-car-grid').replaceChildren();$('race-owned-grid').replaceChildren();
  for(const car of CARS){const owned=p.unlockedCars.includes(car.id),selected=p.selectedCarId===car.id,card=document.createElement('article'),preview=document.createElement('canvas'),b=document.createElement('button');card.className=selected?'selected':'';card.dataset.car=car.id;preview.width=84;preview.height=132;preview.setAttribute('aria-hidden','true');const pc=preview.getContext('2d');pc.scale(2,2);drawRaceCar(pc,21,33,21,42,0,car);const words=document.createElement('div');words.innerHTML=`<small>${car.category==='supercar'?'🔥 ':''}${car.tag}</small><h3>${car.name}</h3><span>${garage.data.upgrades[car.id].speed>1?'튜닝 ':''}${car.maxSpeed+(garage.data.upgrades[car.id].speed-1)*11} km/h</span><small>핸들링 ${Math.round(car.handling*650)} · 부스트 ${Math.round(car.nitroPower*50)}</small>`;b.type='button';b.dataset.carAction=car.id;b.textContent=selected?'선택 완료 ✓':owned?'차량 선택':`🪙 ${money(car.price)}`;b.disabled=selected||!owned&&p.coins<car.price;b.onclick=()=>safe(()=>{garage.chooseCar(car.id);api.effect('special');renderGarage();});card.append(preview,words,b);if(p.selectedCategory==='all'||p.selectedCategory===car.category)$('race-car-grid').append(card);if(owned){const copy=card.cloneNode(true);copy.querySelector('button').onclick=b.onclick;const cv=copy.querySelector('canvas');cv.getContext('2d').drawImage(preview,0,0);$('race-owned-grid').append(copy);}}
  $('race-difficulties').replaceChildren();for(const diff of Object.values(DIFFICULTIES).filter(d=>d.id!=='hard')){const b=document.createElement('button');b.type='button';b.dataset.difficulty=diff.id;b.setAttribute('aria-pressed',String(diff.id===p.selectedDifficulty));const locked=diff.id==='hell'&&!garage.hardUnlocked;b.disabled=locked;b.innerHTML=`<strong>${locked?'🔒 ':''}${diff.label}</strong><small>${(diff.length/1000).toFixed(1)} km · ${diff.id==='easy'?'직선 도로':diff.id==='hard'?'완만한 커브':'급커브 주행'}</small><span>${locked?`쉬움3위 이내 ${Math.min(3,p.mediumPodiums)}/3회`:`1위 +${money(Math.round(diff.reward*(1+(p.stage-1)*.15)))} 🪙`}</span>`;b.onclick=()=>safe(()=>{garage.select('selectedDifficulty',diff.id);renderGarage();});$('race-difficulties').append(b);}
  if(p.selectedDriveMode==='drive'){$('race-difficulties').replaceChildren();for(const [id,name,note]of [['endless','무한주행','편하게 끝없이 달리기'],['hard','어려움','더 위험한 급커브'],['police','경찰 추격','별이 늘수록 거세지는 추격']]){const b=document.createElement('button');b.type='button';b.dataset.scenario=id;b.setAttribute('aria-pressed',String(p.selectedDriveScenario===id));b.innerHTML=`<strong>${name}</strong><small>${note}</small>`;b.onclick=()=>safe(()=>{garage.select('selectedDriveScenario',id);renderGarage();});$('race-difficulties').append(b);}}
  $('race-start').textContent=p.activeRace&&(p.activeRace.mode||'race')===p.selectedDriveMode&&(p.selectedDriveMode!=='drive'||(p.activeRace.scenario||'endless')===p.selectedDriveScenario)?'▶ 저장된 주행 이어가기':p.selectedDriveMode==='drive'?'일반 도로주행 시작 →':`STAGE ${p.stage} · 레이싱 출발 →`;$('race-fresh').hidden=!p.activeRace;
 }
 $('race-categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b)safe(()=>{garage.select('selectedCategory',b.dataset.category);renderGarage();});};
 function start(fresh=false){
  if(!garage)return;if(garage.data.selectedDriveMode==='race'&&garage.data.selectedDifficulty==='hell'&&!garage.hardUnlocked)throw Error('쉬움 레이싱에서3위 이내로3회 완주하면 어려움이 열려요.');resetInputs();engine.unlock(api.settings?.());const pending=garage.data.activeRace;if(!fresh&&pending&&((pending.mode||'race')!==garage.data.selectedDriveMode||garage.data.selectedDriveMode==='drive'&&(pending.scenario||'endless')!==garage.data.selectedDriveScenario)){if(!confirm('저장된 주행을 끝내고 선택한 모드로 새로 출발할까요?'))return;fresh=true;}const next=!fresh&&pending?RaceSimulation.restore(pending):null;
  const candidate=next||new RaceSimulation({car:garage.car,difficulty:garage.data.selectedDriveMode==='drive'?(garage.data.selectedDriveScenario==='hard'?'hell':'hard'):garage.data.selectedDifficulty,stage:garage.data.stage,mode:garage.data.selectedDriveMode,scenario:garage.data.selectedDriveScenario});garage.checkpoint(candidate);race=candidate;settled=null;hasResult=false;manualPause=false;last=0;autosave=0;root.dataset.raceView='play';$('race-garage').hidden=true;$('race-play').hidden=false;$('race-result').hidden=true;$('race-paused').hidden=true;
  $('race-track').querySelectorAll('.race-rival-marker').forEach(e=>e.remove());for(let i=0;i<race.rivals.length;i++){const marker=document.createElement('span');marker.className='race-rival-marker';marker.id='race-rival-'+i;marker.textContent=['😈','👾','👹','🤖','👽','💀'][i];$('race-track').append(marker);}canvas.focus({preventScroll:true});updateHud();api.active(true);
 }
 function toGarage(){if(race?.mode==='drive'&&['countdown','racing'].includes(race.phase)){race.finishDrive();settle();}else if(race?.phase==='finished')settle();else save();resetInputs();race=null;manualPause=false;root.dataset.raceView='garage';$('race-play').hidden=true;$('race-garage').hidden=false;renderGarage();api.active(false);}
 function pause(){resetInputs();if(race&&['countdown','racing'].includes(race.phase)){manualPause=true;$('race-paused').hidden=false;}safe(save);}
 function settle(){if(settled)return settled;settled=garage.finish(race.result);return settled;}
 function showResult(){
  if(race.mode==='drive'){showDriveResult();return;}
  const r=race.result;resetInputs();hasResult=true;try{settle();$('race-result-status').textContent=r.rank<=3?'보상과 다음 스테이지를 저장했어요.':'보상을 저장했어요. 3위 안에 입상하면 다음 스테이지가 열려요.';}catch(error){$('race-result-status').textContent='보상 저장을 다시 시도해 주세요. '+error.message;}
  const bonus=Math.round(race.diff.reward*(1+(r.stage-1)*.15)*[0,1,.7,.5,.35,.25,.2,.15][r.rank]);
  $('race-result-icon').textContent=['','🏆','🥈','🥉','🔥','⚡','💨','🏁'][r.rank];$('race-result-title').textContent=`${r.rank}위 · ${r.rank===1?'압도적 챔피언!':r.rank<=3?'입상 성공!':'다시 도전해요!'}`;$('race-result-stage').textContent=r.rank<=3?`${race.diff.label} · STAGE ${r.stage} → ${r.stage+1}`:`${race.diff.label} · STAGE ${r.stage} 재도전`;$('race-result-next').textContent=r.rank<=3?'다음 스테이지 →':'같은 스테이지 재도전';$('race-result-details').replaceChildren();
  for(const [label,value]of [['주행 시간',r.seconds.toFixed(1)+'초'],['도로 코인 · 이벤트','+'+money(r.trackCoins)+' 🪙'],['순위 완주 보상','+'+money(bonus)+' 🪙'],['총 획득 동전','+'+money(r.trackCoins+bonus)+' 🪙']]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);$('race-result-details').append(row);}
  $('race-countdown').hidden=true;$('race-result').hidden=false;api.effect('special');updateWallet();
 }
 function showDriveResult(){const r=race.result;resetInputs();hasResult=true;try{settle();$('race-result-status').textContent='모은 동전과 주행 기록을 저장했어요.';}catch(error){$('race-result-status').textContent=error.message;}$('race-result-icon').textContent='🚗';$('race-result-title').textContent=r.crashed?'체력 소진 · 주행 종료':'자유주행 완료';$('race-result-stage').textContent=(race.distance/1000).toFixed(2)+' km · 남은 체력 '+race.hp+'/100';$('race-result-next').textContent='다시 주행하기 →';$('race-result-details').replaceChildren();const row=document.createElement('div');row.textContent='주행 보상 🪙 '+money(r.trackCoins);$('race-result-details').append(row);$('race-result').hidden=false;$('race-countdown').hidden=true;api.effect('over');updateWallet();}
 $('race-games').onclick=()=>{safe(save);api.open('game-picker-dialog');};$('race-garage-open').onclick=()=>api.open(carPanel.id);$('race-shop-open').onclick=()=>api.open(shopPanel.id);$('race-upgrade-open').onclick=()=>api.open(tuningPanel.id);$('race-drive-modes').onclick=e=>{const b=e.target.closest('[data-drive-mode]');if(b)safe(()=>{garage.select('selectedDriveMode',b.dataset.driveMode);renderGarage();});};
 $('race-start').onclick=()=>safe(()=>start());$('race-fresh').onclick=()=>safe(()=>{if(confirm('저장된 주행 대신 새로 출발할까요? 차량과 동전은 유지돼요.'))start(true);});$('race-home').onclick=()=>safe(toGarage);$('race-pause').onclick=pause;$('race-resume').onclick=()=>{resetInputs();engine.unlock(api.settings?.());manualPause=false;last=0;$('race-paused').hidden=true;};
 $('race-result-garage').onclick=()=>safe(()=>{settle();toGarage();});$('race-result-next').onclick=()=>safe(()=>{settle();start(true);});$('race-sound').onclick=()=>{api.toggleSound?.();engine.unlock(api.settings?.());updateWallet();};
 for(const button of root.querySelectorAll('[data-drive]')){button.onpointerdown=e=>{if(e.button>0||blocked()||manualPause||!['countdown','racing'].includes(race?.phase))return;e.preventDefault();engine.unlock(api.settings?.());touches.set(e.pointerId,button.dataset.drive);button.setPointerCapture?.(e.pointerId);button.classList.add('pressed');};const release=e=>{touches.delete(e.pointerId);if(![...touches.values()].includes(button.dataset.drive))button.classList.remove('pressed');};for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,release);}

 const keys={ArrowUp:'accel',KeyW:'accel',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',};
 const physicalKeys=new Set();document.addEventListener('keydown',e=>{if(blocked()||manualPause||!race||!['countdown','racing'].includes(race.phase)||/INPUT|TEXTAREA|SELECT/.test(e.target?.tagName))return;if(keys[e.code]){e.preventDefault();physicalKeys.add(e.code);heldKeys.add(keys[e.code]);engine.unlock(api.settings?.());}if(e.code==='Escape')pause();});document.addEventListener('keyup',e=>{physicalKeys.delete(e.code);const key=keys[e.code];if(key&&![...physicalKeys].some(code=>keys[code]===key))heldKeys.delete(key);});
 globalThis.addEventListener('blur',()=>{physicalKeys.clear();if(active())pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){physicalKeys.clear();if(active())pause();}});globalThis.addEventListener('pagehide',()=>{engine.mute();safe(save);});
 function updateHud(){
  const t=raceTelemetry(race);$('race-speed').textContent=t.speed;$('race-rpm').textContent=t.rpm.toLocaleString('ko-KR');$('race-gear').textContent='D'+t.gear;$('race-rpm-needle').style.transform='rotate('+Math.max(0,Math.min(180,t.rpm/8000*180))+'deg)';$('race-speed-needle').style.transform='rotate('+Math.max(0,Math.min(180,t.speed/320*180))+'deg)';$('race-hud-stage').textContent=race.mode==='drive'?'ROAD TRIP':'STAGE '+race.stage;$('race-hud-diff').textContent=race.mode==='drive'?({endless:'무한주행',hard:'어려움',police:'경찰 추격'}[race.scenario]):race.diff.label;$('race-collected').textContent='🪙 +'+money(race.trackCoins);$('race-position').textContent=race.mode==='drive'?(race.distance/1000).toFixed(2)+' km 주행':`${race.rank}위 / 7대 ${race.rank===1?'🏆':''}`;$('race-track').hidden=race.mode==='drive';$('race-progress-start').textContent=race.mode==='drive'?'일반 도로주행':'START';$('race-progress-end').textContent=race.mode==='drive'?'♥ '+race.hp+'/100'+(race.scenario==='police'?' · '+'★'.repeat(race.wanted)+'☆'.repeat(6-race.wanted):''):'FINISH 🏁';$('race-home').textContent=race.mode==='drive'?'주행 마치기':'차고로';$('race-pad-status').textContent=race.boosting?'⚡ BOOST! 발판 가속 중':'도로 곳곳의 부스트 발판을 밟아보세요 ⚡';$('race-pad-status').classList.toggle('active',race.boosting);
  const pct=Math.min(100,race.distance/race.length*100);$('race-progress-fill').style.width=pct+'%';$('race-player-marker').style.left=pct+'%';race.rivals.forEach((r,i)=>{const m=$('race-rival-'+i);if(m)m.style.left=Math.min(100,r.distance/race.length*100)+'%';});
  $('race-countdown').hidden=race.phase!=='countdown';$('race-countdown').textContent=Math.max(1,Math.ceil(race.countdown/.75));const sharp=(race.curve(race.distance+220)-race.curve(race.distance+160))/60;$('race-event').hidden=!(race.mode==='drive'&&race.scenario==='police')&&!(Math.abs(sharp)>.24&&race.speed>7);$('race-event').textContent=race.mode==='drive'&&race.scenario==='police'?`🚨 경찰 추격 · ${race.wanted}단계`:`${sharp>0?'↪':'↩'} 급커브 · 가속을 놓아 속도를 줄이세요`;
 }
 function frame(now){const dt=last?Math.min(.1,(now-last)/1000):0;last=now;
  if(active()&&race){const bounds=canvas.getBoundingClientRect(),w=Math.max(1,bounds.width),h=Math.max(1,bounds.height),dpr=Math.min(2,globalThis.devicePixelRatio||1),scale=Math.min(w/600,h/500),controls=root.querySelector('.race-controls').getBoundingClientRect().height||120,bottom=Math.max(187,(Math.min(150,controls)+34*scale+28)/scale);race.setViewport(h/scale,bottom);const paused=blocked()||manualPause;const input=drive();if(!paused){race.update(dt,input);for(const event of race.events.splice(0)){if(event.type==='coin')api.effect('merge');if(['jump','escaped','go','boost'].includes(event.type))api.effect('special');if(event.type==='hit')api.effect('over');if(event.type==='police')api.toast('🚨 경찰 추격전! 점프대나 부스트 발판으로 따돌리세요.');}if(race.phase==='finished'&&!hasResult)showResult();autosave+=dt;if(autosave>5&&race.phase!=='finished'){autosave=0;safe(save);}}
   else resetInputs();if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle=race.diff.scenery;ctx.fillRect(0,0,w,h);ctx.setTransform(dpr*scale,0,0,dpr*scale,(w-600*scale)/2*dpr,0);drawRaceScene(ctx,race,now/1000,input,h/scale,bottom);updateHud();engine.update({active:!paused&&['countdown','racing'].includes(race.phase),running:race.phase==='racing',racing:race.mode==='race',speed:race.speed/race.car.scrollSpeed,throttle:input.accel,gear:raceTelemetry(race).gear,boosting:race.boosting},api.settings?.());
  }else engine.mute();requestAnimationFrame(frame);
 }
 requestAnimationFrame(frame);
 const select=()=>{garage||=new RacingGarage();garage.save();if(!race){root.dataset.raceView='garage';$('race-garage').hidden=false;$('race-play').hidden=true;renderGarage();}else pause();};
 function openLocker(){if(!garage)select();if(race)toGarage();$('race-garage').hidden=false;api.open(shopPanel.id);}
 const records=document.createElement('dialog');records.id='race-records-dialog';records.className='wide-dialog';records.innerHTML='<button type="button" class="dialog-close" aria-label="레이싱 기록 닫기">×</button><p class="eyebrow">SPEED GARDEN RECORDS</p><h2>나의 레이싱 기록</h2><dl></dl><p class="race-records-note"></p>';document.body.append(records);records.querySelector('button').onclick=()=>records.close();records.addEventListener('close',api.resume);
 function openRecords(){if(!garage)select();const p=garage.data,list=records.querySelector('dl');list.replaceChildren();for(const [name,value]of [['현재 스테이지',p.stage],['완주한 레이스',p.completedRaces+'회'],['우승',p.wins+'회'],['최고 순위',p.completedRaces?p.bestRank+'위':'아직 없음'],['누적 획득 동전',money(p.earnedCoins)],['주행 시간',money(p.seconds)+'초'],['보유 차량',p.unlockedCars.length+' / 18']]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;row.append(dt,dd);list.append(row);}records.querySelector('.race-records-note').textContent=`5회 완주마다 공용 보석 5개 · 다음 보상까지 ${5-p.completedRaces%5}회`;api.open(records.id);}

 $('race-records-open').onclick=openRecords;
 return {select,save,leave:pause,openLocker,openRecords,focusMode:()=>{if(race)toGarage();$('race-difficulties').focus?.();},restart:()=>safe(()=>{if(confirm('차량과 동전을 유지하고 레이스를 다시 시작할까요?'))start(true);}),mode:()=> 'classic',model:()=>garage,simulation:()=>race};
}
